<script lang="ts">
 import { onMount } from 'svelte'; import { base } from '$app/paths'; import { db } from '$lib/db'; import { createId } from '$lib/id'; import type { Drawing } from '$lib/types';
 let drawings=$state<Drawing[]>([]), counts=$state<Record<string,number>>({}), title=$state(''), loading=$state(true), creating=$state(false), error=$state('');
 async function refresh(){drawings=await db.drawings.orderBy('createdAt').reverse().toArray();counts=Object.fromEntries(await Promise.all(drawings.map(async d=>[d.id,await db.stages.where('drawingId').equals(d.id).count()] as const)));}
 onMount(async()=>{try{await refresh();}catch(e){error='Local storage could not be opened.';}finally{loading=false;}});
 async function create(){if(creating)return;creating=true;error='';try{const name=title.trim()||'Untitled drawing', drawing={id:createId(),title:name,createdAt:Date.now()};await db.drawings.add(drawing);title='';await refresh();}catch(e){console.error('Could not create drawing:',e);error=e instanceof Error?`Could not create drawing: ${e.message}`:'Could not create drawing. Check that browser storage is available.';}finally{creating=false;}}
 async function rename(d:Drawing){const value=prompt('Drawing title',d.title);if(value?.trim()){await db.drawings.update(d.id,{title:value.trim()});await refresh();}}
 async function remove(d:Drawing){if(!confirm(`Delete “${d.title}” and all its stages? This cannot be undone.`))return;await db.transaction('rw',db.drawings,db.stages,async()=>{await db.stages.where('drawingId').equals(d.id).delete();await db.drawings.delete(d.id);});await refresh();}
</script>
<div class="app"><header class="topbar"><a class="brand" href={`${base}/`}><span class="brand-mark">✳</span>Skepanion</a><nav class="nav"><a href={`${base}/palettes`}>My colors</a><a href={`${base}/monthly`}>Monthly</a><a href={`${base}/backup`}>Backup</a></nav></header>
<p class="eyebrow">A little progress, every time</p><h1>Your sketchbook, growing.</h1><p class="muted">Keep a photo timeline for each drawing and notice the colors along the way. Your work stays on this device.</p>
<section class="section card"><form class="row" onsubmit={(e)=>{e.preventDefault();void create();}}><div class="field" style="flex:1;min-width:180px;margin:0"><label for="drawing-title">Start a drawing</label><input id="drawing-title" bind:value={title} placeholder="e.g. Sunday garden study" maxlength="80"/></div><button class="button" type="submit" disabled={creating}>{creating?'Creating…':'＋ New drawing'}</button></form>{#if error}<p role="alert" style="color:#a33;margin-bottom:0">{error}</p>{/if}</section>
<section class="section"><div class="row" style="justify-content:space-between"><h2>Your drawings</h2><span class="muted">{drawings.length} {drawings.length===1?'drawing':'drawings'}</span></div>
{#if loading}<p class="muted">Loading your sketchbook…</p>{:else if error}<div class="card">{error}</div>{:else if drawings.length===0}<div class="card empty-card"><div style="font-size:40px">📖</div><h2>Your first page is waiting</h2><p class="muted">Create a drawing above, then add a photo whenever you make progress.</p></div>{:else}<div class="grid">{#each drawings as drawing}<article class="card"><p class="eyebrow">Started {new Date(drawing.createdAt).toLocaleDateString()}</p><h2 style="margin:8px 0 14px">{drawing.title}</h2><p class="muted">{counts[drawing.id]??0} {(counts[drawing.id]??0)===1?'stage':'stages'}</p><div class="row"><a class="button" href={`${base}/drawing/${drawing.id}`}>Open drawing →</a><button class="button secondary" onclick={()=>void rename(drawing)} aria-label={`Rename ${drawing.title}`}>Rename</button><button class="button danger" onclick={()=>void remove(drawing)} aria-label={`Delete ${drawing.title}`}>Delete</button></div></article>{/each}</div>{/if}</section></div>
